            qty = int(qty_s)
        except ValueError:
            rejected.append(i)
            continue
        if op == "add":
            if qty < 0:
                rejected.append(i)
                continue
            inv[sku] = inv.get(sku, 0) + qty
        elif op == "remove":
            if qty < 0 or sku not in inv or inv[sku] - qty < 0:
                rejected.append(i)
                continue
            inv[sku] -= qty
        else:
            rejected.append(i)

    with open("inventory_after.json", "w") as f:
        json.dump(inv, f, indent=2)
        f.write("\n")

    with open("rejected.txt", "w") as f:
        for n in rejected:
            f.write(f"{n}\n")


